print('MDP transition probabilities are valid.')

def expected_reward(outcomes):
    total_probability = sum(probability for probability, _, _, _ in outcomes)
    if abs(total_probability - 1.0) > 1e-9:
        raise ValueError('Transition probabilities must sum to 1')
    return sum(probability * reward for probability, _, reward, _ in outcomes)

outcomes = [(0.7, 1, 5.0, False), (0.3, 2, -2.0, False)]
print(expected_reward(outcomes))

def evaluate_policy(mdp, policy, gamma=0.9, iterations=100):
    states = list(mdp)
    values = {state: 0.0 for state in states}

    for _ in range(iterations):
        updated = values.copy()
        for state in states:
            if not mdp[state]:
                updated[state] = 0.0
                continue
            action = policy[state]
            total = 0.0
            for probability, next_state, reward, terminated in mdp[state][action]:
                future = 0.0 if terminated else values[next_state]
                total += probability * (reward + gamma * future)
            updated[state] = total
        values = updated

    return values

policy = {0: 1, 1: 1}
print(evaluate_policy(mdp, policy))
